<template>  <div class="auth-card">    <h1>Реєстрація</h1>    <form @submit.prevent="submit">      <label>        Пошта        <input v-model.trim="email" type="email" placeholder="you@example.com" required />      </label>      <label>        Пароль        <input v-model="password" type="password" placeholder="********" required />      </label>      <label>        Підтвердження пароля        <input v-model="confirm" type="password" placeholder="********" required />      </label>      <ul class="hints">        <li :class="{ ok: password.length >= 8 }">Мінімум 8 символів</li>        <li :class="{ ok: /[A-ZА-ЯІЇЄ]/.test(password) }">Велика літера</li>        <li :class="{ ok: /[a-zа-яіїє]/.test(password) }">Мала літера</li>        <li :class="{ ok: /\d/.test(password) }">Цифра</li>      </ul>      <p v-if="error" class="error">{{ error }}</p>      <button type="submit" class="primary">Створити акаунт</button>    </form>    <div class="links">      <RouterLink to="/login">Вже маєте акаунт? Увійти</RouterLink>    </div>  </div></template><script setup>import { ref } from 'vue'import { useRouter } from 'vue-router'import { register, authError } from '@/stores/auth'const router = useRouter()const email = ref('')const password = ref('')const confirm = ref('')const error = authErrorasync function submit() {  const ok = await register(email.value, password.value, confirm.value)  if (ok) {    router.replace({ name: 'login' })  }}</script><style scoped>.auth-card { max-width: 480px; margin: 8vh auto; padding:1.25rem; background:#fff; border:1px solid #e5e7eb; border-radius:10px; box-shadow:0 6px 24px rgba(0,0,0,.08); color: #111111 }label { display:block; margin: .75rem 0; font-weight: 600; }input { width:100%; padding:.6rem .7rem; border:1px solid #d1d5db; border-radius:8px; margin-top:.35rem; }button.primary { width:100%; margin-top:1rem; padding:.6rem .7rem; background:#2563eb; color:#fff; border:none; border-radius:8px; cursor:pointer; }button.primary:hover { background:#2563eb; }.error { color:#b91c1c; margin-top:.5rem; }.hints { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:.25rem .75rem; margin:.5rem 0 0; padding-left:1rem; }.hints li { color:#6b7280; }.hints li.ok { color:#2563eb; }</style>